INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.139Z', '2026-08-13T13:52:44.139Z', NULL, E'1646', E'196', 3, E'2. Desarrollar planes integrados de inversión, mantenimiento,  conservación y ampliación, en concordancia con el Plan Maestro  de Infraestructura y en función del crecimiento y racionalización del  parque inmobiliario de la UMSA. ', E'Reglamento Especial  para la Concesión, Uso  y Mantenimiento de  Instalaciones y Campos  Deportivos De La  UMSA HCU 86 2013_27.02.2013 ');
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.140Z', '2026-08-13T13:52:44.140Z', NULL, E'1652', E'196', 4, E'8. Ejecutar una gestión administrativa eficiente, mediante la  aplicación de los sistemas institucionales vigentes en la UMSA y el  cumplimiento de la normativa interna.', NULL);
