INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.142Z', '2026-08-13T13:52:44.142Z', NULL, E'1695', E'198', 2, E'b. Formular y ejecutar el plan operativo anual de la unidad.', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.143Z', '2026-08-13T13:52:44.143Z', NULL, E'1696', E'198', 3, E'c. Desarrollar programas y proyectos de investigación, en el marco de las líneas de investigación institucionales.', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.144Z', '2026-08-13T13:52:44.144Z', NULL, E'1697', E'198', 4, E'd. Promover la investigación básica y aplicada en áreas estratégicas de acuerdo con las necesidades sociales, económicas y ambientales del país y la región.', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.145Z', '2026-08-13T13:52:44.145Z', NULL, E'1698', E'198', 5, E'e. Identificar fuentes de financiamiento para la investigación, tanto nacionales como internacionales, y gestionar los recursos necesarios para llevar a cabo los proyectos.', NULL);
