INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.146Z', '2026-08-13T13:52:44.146Z', NULL, E'1700', E'198', 7, E'g. Proponer y gestionar alianzas estratégicas para la suscripción de Convenios de cooperación interinstitucional, con entidades públicas y privadas además de ONGs y cooperación internacional en temas de investigación e interacción social.', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.147Z', '2026-08-13T13:52:44.147Z', NULL, E'1701', E'198', 8, E'h. Publicar y difundir la producción intelectual generada por la investigación.', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.148Z', '2026-08-13T13:52:44.148Z', NULL, E'1702', E'198', 9, E'i. Conformar redes con investigadores de otras Universidades en el ámbito nacional y extranjero, así como con organizaciones públicas y privadas de investigación.', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.149Z', '2026-08-13T13:52:44.149Z', NULL, E'1703', E'198', 10, E'j. Desarrollar programas de formación para fortalecer las capacidades investigativas de los docentes, estudiantes y personal asociado al instituto.', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.149Z', '2026-08-13T13:52:44.149Z', NULL, E'1704', E'198', 11, E'k. Promover la participación de estudiantes de grado y posgrado en proyectos de investigación, fomentando una cultura de investigación desde tempranas etapas académicas.', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.151Z', '2026-08-13T13:52:44.151Z', NULL, E'1705', E'198', 12, E'l. Facilitar la movilidad académica de docentes investigadores para la participación en congresos, seminarios y cursos de especialización a nivel nacional e internacional.', NULL);
