INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.152Z', '2026-08-13T13:52:44.152Z', NULL, E'1707', E'198', 14, E'n. Promover la publicación de las investigaciones en revistas indexadas a nivel nacional e internacional.', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.153Z', '2026-08-13T13:52:44.153Z', NULL, E'1708', E'198', 15, E'o. Organizar y participar en congresos, simposios, talleres y conferencias para presentar los avances de las investigaciones realizadas.', NULL);
