INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.161Z', '2026-08-13T13:52:44.161Z', NULL, E'1714', E'198', 21, E'u. Participar en proyectos de investigación internacionales que permitan acceder a nuevas tecnologías y metodologías.', NULL);
