INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.166Z', '2026-08-13T13:52:44.166Z', NULL, E'1719', E'198', 26, E'z. Gestionar de manera eficiente el capital humano, materiales, equipos, infraestructura y recursos económicos asignados a la unidad.', NULL);
