INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.168Z', '2026-08-13T13:52:44.168Z', NULL, E'1784', E'61', 12, E'c. Organizar las sesiones del gobierno y cogobierno facultativo.', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.169Z', '2026-08-13T13:52:44.169Z', NULL, E'1794', E'61', 13, E'm. Emitir informe de gestión a requerimiento de instancias superiores.', NULL);
