INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.170Z', '2026-08-13T13:52:44.170Z', NULL, E'1837', E'117', 5, E'l. Facilitar la movilidad académica de docentes investigadores para la participación en congresos, seminarios y cursos de especialización a nivel nacional e internacional.', NULL);
