INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.215Z', '2026-08-13T13:52:44.215Z', NULL, E'980', E'169', 11, E'8. Elaborar informes estadísticos con los indicadores clave solicitados.', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.174Z', '2026-08-13T13:52:44.174Z', NULL, E'943', E'166', 16, E'13. Revisar y proponer, normativa interna y específica, relacionada con la  administración de actividades y funciones de la Unidad, así como de la  utilización de recursos y otras relacionadas.', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.175Z', '2026-08-13T13:52:44.175Z', NULL, E'947', E'167', 1, E'1. Recibir denuncias de miembros de la comunidad universitaria que  consideren estar siendo vulnerados en sus derechos constitucionales  y derechos humanos en general, previstos como tal en la normativa  internacional. ', E'Reglamento de la  Defensoría de los  Derechos  Universitarios  adjunto a  Resolución  Honorable  Consejo  Universitario N°  615/2013 ');
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.176Z', '2026-08-13T13:52:44.176Z', NULL, E'948', E'167', 2, E'2. Investigar los casos denunciados ante sus oficinas, en aras de su  esclarecimiento y pronta enmienda o solución o reparación. ', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.178Z', '2026-08-13T13:52:44.178Z', NULL, E'949', E'167', 3, E'3. Investigar de oficio sobre la existencia de situaciones o mecanismos  que generen vulneración sistemática de los derechos humanos al  interior de la universidad, a efecto de promover su extinción. ', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.179Z', '2026-08-13T13:52:44.179Z', NULL, E'950', E'167', 4, E'4. Promover acciones de entendimiento y conciliación, ante conflictos que  se susciten al interior de la universidad, para lograr soluciones pacíficas  y consensuadas, al margen de cualquier hecho de violencia,  desarrollando una labor mediadora. ', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.180Z', '2026-08-13T13:52:44.180Z', NULL, E'951', E'167', 5, E'5. Promover programas de difusión de los derechos constitucionales y  derechos humanos en general, al interior de la universidad, haciendo  énfasis en la igualdad de derechos e igualdad de género. ', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.181Z', '2026-08-13T13:52:44.181Z', NULL, E'952', E'167', 6, E'6. Promover la educación y concientización en derechos humanos dentro  la universidad, gestionando la incorporación de esta temática en los  programas de estudios de las diferentes carreras, en aras del establecimiento de una cultura de los derechos humanos en la  universidad. ', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.182Z', '2026-08-13T13:52:44.182Z', NULL, E'1162', E'59', 2, E'd. Supervisar la ejecución de las políticas académicas y administrativas institucionales.', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.182Z', '2026-08-13T13:52:44.182Z', NULL, E'953', E'167', 7, E'7. Interpelar y denunciar toda conducta discriminatoria practicada en la  universidad, sea por razones raciales, étnicas, religiosas, ideológicas,  políticas, económicas, de género, generacionales, xenofóbicas,  misóginas u homofóbicas.', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.183Z', '2026-08-13T13:52:44.183Z', NULL, E'954', E'167', 8, E'8. Promover el respeto y la práctica de la libertad de pensamiento y  expresión dentro la Universidad. ', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.184Z', '2026-08-13T13:52:44.184Z', NULL, E'955', E'167', 9, E'9. Promover la promulgación de normas jurídicas que reivindiquen los  derechos humanos dentro la universidad, así como impulsar la  derogación u abrogatoria de todo instrumento jurídico que tienda a  vulnerar derechos constitucionales y la normativa internacional vigente  en materia de derechos humanos.', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.185Z', '2026-08-13T13:52:44.185Z', NULL, E'956', E'167', 10, E'10. Dictar RESOLUCIÓNes defensoriales como emergencia de denuncias  comprobadas contra autoridades universitarias sobre violación de  derechos, instando a sus autores a subsanar el atropello denunciado,  reparar el daño o corregir procedimiento. Asimismo, en caso de no  comprobarse el hecho denunciado, la resolución desestimará la  denuncia.', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.185Z', '2026-08-13T13:52:44.185Z', NULL, E'957', E'167', 11, E'11. Evacuar informes anuales ante el H. Consejo Universitario, respecto a  la gestión desarrollada. ', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.186Z', '2026-08-13T13:52:44.186Z', NULL, E'958', E'168', 1, E'1. Dirigir y supervisar la formulación e implantación del Plan  Estratégico Institucional (PEI). ', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.187Z', '2026-08-13T13:52:44.187Z', NULL, E'959', E'168', 2, E'2. Supervisar los procesos de seguimiento y evaluación del  PEI. ', E'Reglamento Específico del  Sistema de Planificación de  la UMSA, aprobado con Res.  HCU 185/20 del 29/7/2020 ');
