INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.495Z', '2026-08-13T13:52:44.495Z', NULL, E'1120', E'178', 1, E'1. Atender y responder consultas jurídicas presentadas por las  unidades académicas y administrativas, mediante la redacción  de notas, informes o dictámenes jurídicos en el marco de la  normativa vigente. ', E'del Estado (CPE)  Art. 92 y Art. 93:  Reconocen la autonomía  universitaria y la potestad  de las universidades  públicas para regirse por  sus propias normas en el  marco de la Constitución  y la ley.  Art. 115 y Art. 117:  Garantizan el derecho al  debido proceso y a la  defensa legal, principios  que fundamentan la  existencia de una  instancia asesora  jurídica en toda entidad  pública. ');
