INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.498Z', '2026-08-13T13:52:44.498Z', NULL, E'1122', E'178', 3, E'3. Respaldar mediante criterio legal los Informes  Circunstanciados y Relevamiento de Información emitidos por  el Departamento de Auditoría Interna. ', E'Ley Nº 1178 – Sistema  de Administración y  Control  Gubernamentales (SAFCO)  Art. 3 Alcances de la Ley  Nº 1178.  Art. 29 Responsabilidad  por la Función Pública  (Administrativa) ');
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.499Z', '2026-08-13T13:52:44.499Z', NULL, E'1152', E'179', 1, E'17. Verificar el Control Interno Implementado de acuerdo a la  naturaleza de su actividad.  ', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.500Z', '2026-08-13T13:52:44.500Z', NULL, E'1123', E'178', 4, E'4. Expedir criterios legales para el inicio de procesos  disciplinarios internos universitarios y/o administrativos,  conforme a normativa universitaria y disposiciones legales  vigentes. ', E'Decretos que regulan  los Sistemas: SOA,  SPO, SP, SABS, SCI y  SCG.');
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.501Z', '2026-08-13T13:52:44.501Z', NULL, E'1124', E'178', 5, E'5. Asesorar a la Comisión de Procesos Administrativos. ', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.502Z', '2026-08-13T13:52:44.502Z', NULL, E'1125', E'178', 6, E'6. Asesorar a las autoridades universitarias en la resolución de  procesos en instancia de impugnación administrativa. ', E'Ley Nº 2341 – Ley de  Procedimiento  Administrativo  Art. 2 Ámbito de  aplicación, párrafo III   “Las Universidades  Públicas, aplicarán la  presente Ley en el  marco de la Autonomía  Universitaria” ');
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.503Z', '2026-08-13T13:52:44.503Z', NULL, E'1126', E'178', 7, E'7. Presentar denuncias y recursos de impugnación  administrativa ante las autoridades competentes en defensa  de los intereses universitarios.', NULL);
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.505Z', '2026-08-13T13:52:44.505Z', NULL, E'1127', E'178', 8, E'8. Gestionar la regularización del derecho propietario de  inmuebles de la UMSA, incluyendo las exenciones  impositivas, llevando un registro actualizado de las  propiedades, además de la guarda y custodia de los  documentos de propiedad. ', E'Normativa del Sistema  Universitario  Boliviano.  Estatuto Orgánico de  la UMSA  Art. 4. Principios I. Son  principales de la UMSA:   a) La Autonomía  universitaria. ');
INSERT INTO "unidad_funcion" ("created_at", "updated_at", "deleted_at", "id", "unidad_id", "orden", "funcion", "base_legal") VALUES ('2026-08-13T13:52:44.507Z', '2026-08-13T13:52:44.507Z', NULL, E'1128', E'178', 9, E'9. Gestionar la regularización del derecho propietario del parque  automotor de la UMSA, incluyendo exenciones impositivas,  llevando un registro actualizado de los motorizados  universitarios, además de la guarda y custodia de los  documentos de propiedad. ', NULL);
